  (5939, 'yours', 'pronoun', 'a2', '4.0 - 4.5', '/jɔːz/', '/jərz/', 'cái của anh, cái của chị, cái của ngài, cái của mày, cái của các anh, cái của các chị, ...', 'of or belonging to you', 'Is that book yours?', 'Cuốn sách đó có phải của bạn không?', '{}'::text[], '{}'::text[], '{}'::text[], '{}'::jsonb, 'yours_uk.mp3', 'yours_us.mp3', 'Discourse Markers & Connectors', 'Pronouns & Determiners'),
  (5940, 'yourself', 'pronoun', 'a1', '3.0 - 3.5', '/jɔːˈself/', '/jɔːrˈself/', '(dùng khi người hay những người đang đối thoại gây ra và bị tác động bởi một hành động) ...', 'used when the person or people being spoken to both cause and are affected by an action', 'Have you hurt yourself?', 'Bạn có làm tổn thương chính mình không?', '{}'::text[], '{}'::text[], '{}'::text[], '{}'::jsonb, 'yourself_uk.mp3', 'yourself_us.mp3', 'Academic, Research & Abstract Concepts', 'Logic, Cause & Effect'),
  (5941, 'youth', 'noun', 'b1', '5.0 - 5.5', '/juːθ/', '/juːθ/', 'thời kỳ đang trẻ (nhất là khoảng giữa thời thơ ấu và lúc trưởng thành), thời thanh niên ...', 'the time of life when a person is young, especially the time before a child becomes an adult', 'in somebody''s youth, He had been a talented musician in his youth.', 'trong tuổi trẻ của ai đó, Anh ấy đã từng là một nhạc sĩ tài năng khi còn trẻ.', ARRAY['in somebody''s youth']::text[], ARRAY['younker', 'juvenile', 'young', 'cohort']::text[], ARRAY['aged']::text[], '{}'::jsonb, 'youth_uk.mp3', 'youth_us.mp3', 'People, Family & Relationships', 'Life Stages & Age'),
